 T6:[],
 T7:[{title:"t para muestras relacionadas: supuestos",url:"https://youtu.be/480yhCf8pes",page:83},{title:"t para muestras relacionadas: ejemplo práctico",url:"https://youtu.be/I0YXQkw_IFc",page:83},{title:"Wilcoxon relacionado: supuestos y ejemplo práctico",url:"https://youtu.be/aRGs5_FVUdw",page:100},{title:"Wilcoxon relacionado: aplicación en SPSS",url:"https://youtu.be/SHTX-PPc2cg",page:100},{title:"McNemar para dos mediciones binarias relacionadas",url:"https://youtu.be/6PDPZFDTjpU",page:102},{title:"Ejemplo práctico complementario de McNemar",url:"https://youtu.be/TMMR9KYpBFs",page:103},{title:"McNemar–Bowker y Bhapkar para categorías relacionadas",url:"https://youtu.be/OvXJN_tXewE",page:103}],
