function drawSection(){const t=topics.find(x=>x.id===current);tabs.querySelectorAll("[role=tab]").forEach(b=>{const on=+b.dataset.section===section;b.setAttribute("aria-selected",String(on));b.tabIndex=on?0:-1;});content.innerHTML=t.pilot?pilotSection(section):'<p class="content-kicker">'+t.id+' · '+h(labels[section])+'</p><h3>'+h(labels[section])+'</h3>'+pending(section,t)+(section===4?'<div id="routeMount"></div>':'');if(section===4)drawRoute();}
function drawRoute(){const mount=document.getElementById("routeMount");if(!mount)return;const list=trees[current];let node=list[route.i];if(current==="T1"&&route.i===3)node=[list[3][0],list[3][1].filter(o=>o[4]===route.scale)];if(route.result){mount.innerHTML='<div class="route-result"><p class="content-kicker">Ruta terminada · '+route.history.length+' decisiones</p><h4>Análisis de destino</h4><p class="analysis-name">'+h(route.result)+'</p><p>'+h(route.why||"La recomendación depende de la pregunta, el diseño y la estructura de medición descritos en la ruta.")+'</p><p><b>Al informar:</b> '+h(route.report||"estimación, intervalo de confianza y límites del diseño.")+'</p><h4>Decisiones recorridas</h4><ol>'+route.history.map(x=>"<li>"+h(x)+"</li>").join("")+'</ol><button class="small-button primary" id="routeReset">Reiniciar recorrido</button></div>';document.getElementById("routeReset").onclick=()=>{route={i:0,history:[],feedback:null,result:null,selected:null};drawRoute();};return;}mount.innerHTML='<div class="decision-card"><div class="decision-top"><span>'+current+' · Pregunta '+(route.i+1)+' de '+list.length+'</span><span>'+Math.round(route.i/list.length*100)+'%</span></div><div class="progress-track"><div class="progress-fill" style="width:'+Math.round(route.i/list.length*100)+'%"></div></div><h4>'+h(node[0])+'</h4><div class="decision-options">'+node[1].map((o,i)=>'<button type="button" class="decision-option" data-opt="'+i+'"><span class="option-letter">'+String.fromCharCode(65+i)+'</span><span>'+h(o[0])+'</span></button>').join("")+'</div>'+(route.feedback?'<div class="decision-feedback '+(route.feedback.retry?"retry":"")+'" role="status"><p>'+h(route.feedback.text)+'</p>'+(route.feedback.retry?'<button class="small-button" id="retry">Volver a elegir</button>':'<div class="route-controls"><button class="small-button" id="back">← Revisar decisión</button><button class="small-button primary" id="continue">'+(route.feedback.end?"Ver recomendación":"Continuar →")+'</button><button class="small-button" id="reset">Reiniciar</button></div>')+'</div>':'')+'</div>';mount.querySelectorAll("[data-opt]").forEach(b=>b.onclick=()=>{const opt=node[1][+b.dataset.opt];if(opt[2]==="retry"){route.feedback={retry:true,text:opt[1]};drawRoute();return;}if(current==="T1"&&route.i===2)route.scale=opt[4];route.selected=opt;route.feedback={text:opt[1],end:opt[2]==="end"};route.history.push(node[0]+" "+opt[0]);drawRoute();});const retry=document.getElementById("retry");if(retry)retry.onclick=()=>{route.feedback=null;drawRoute();};const cont=document.getElementById("continue");if(cont)cont.onclick=()=>{const o=route.selected;if(o[2]==="end"){let final=o[3];const prior=route.history.join(" ");if(current==="T2"){if(prior.includes("Sí, son adecuadas"))final="Chi-cuadrado de independencia; en tabla 2×2, razón de prevalencias o razón de momios de prevalencia con IC";else if(prior.includes("No, algunas son pequeñas"))final="Fisher exacta para tabla 2×2; para tablas mayores, método exacto/Monte Carlo por definir";}if(current==="T3"){if(prior.includes("Lineal, cuantitativo"))final="Correlación de Pearson";else if(prior.includes("Monotónico u ordinal"))final="Correlación de Spearman";}if(current==="T6"&&prior.includes("Ajustar por covariables")&&o[0].startsWith("No,"))final="Kaplan-Meier descriptivo; no estimar un HR constante hasta definir un modelo alternativo";else if(current==="T6"&&prior.includes("Comparar curvas sin ajuste"))final="Curvas Kaplan-Meier y prueba log-rank; no se estima HR ajustado";if(current==="T9"){if(prior.includes("Sí, medida previa"))final="ANCOVA entre brazos ajustada por la medida basal, con dirección de hipótesis según protocolo";else if(prior.includes("No, solo resultado al seguimiento"))final="Contraste bilateral de desenlace cuantitativo entre los dos brazos al seguimiento";}route.result=final;route.why=o[1];route.report="estadístico o medida con IC 95 %, n, método y límites pertinentes.";drawRoute();return;}route.i++;route.selected=null;route.feedback=null;drawRoute();};const back=document.getElementById("back");if(back)back.onclick=()=>{route.history.pop();route.i=Math.max(0,route.i-1);route.selected=null;route.feedback=null;drawRoute();};const reset=document.getElementById("reset");if(reset)reset.onclick=()=>{route={i:0,history:[],feedback:null,result:null,selected:null};drawRoute();};}
function download(e){e.preventDefault();const names={id:"Identificador",edad_anios:"Edad en años",sexo_registrado:"Sexo registrado",turno:"Turno habitual",imc_kg_m2:"Índice de masa corporal (kg/m²)",prension_kg:"Fuerza de prensión (kg)",caminata_6min_m:"Distancia caminada en 6 minutos (m)",actividad_fisica:"Nivel de actividad física"},keys=Object.keys(people[0]),escapeCsv=v=>{v=String(v);return /[",\n]/.test(v)?'\"'+v.replace(/\"/g,'\"\"')+'\"':v;},csv=[keys.map(k=>escapeCsv(names[k]||k)).join(","),...people.map(p=>keys.map(k=>escapeCsv(p[k])).join(","))].join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\uFEFF",csv],{type:"text/csv;charset=utf-8"}));a.download="estadistica-salud-t1-datos-sinteticos.csv";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function histogram(key,title){const values=people.map(p=>p[key]),min=Math.min(...values),max=Math.max(...values),nBins=6,width=(max-min||1)/nBins,bins=Array(nBins).fill(0);values.forEach(v=>bins[Math.min(nBins-1,Math.floor((v-min)/width))]++);const peak=Math.max(...bins);return '<figure class="histogram"><figcaption>'+title+' <span>n = '+values.length+'</span></figcaption><div class="hist-bars" role="img" aria-label="Histograma de '+title+' con seis intervalos"><div class="hist-y-label">personas</div>'+bins.map((n,i)=>'<div class="hist-bin"><span class="hist-count">'+n+'</span><i style="height:'+Math.max(4,n/peak*100)+'%"></i><small>'+f(min+i*width,0)+'–'+f(min+(i+1)*width,0)+'</small></div>').join("")+'</div><p class="table-caption">Los intervalos son una ayuda visual para inspeccionar esta muestra ficticia.</p></figure>';}
const originalDrawSection=drawSection;
drawSection=function(){originalDrawSection();if(current==="T1"&&section===8)content.insertAdjacentHTML("beforeend",'<div class="histogram-grid">'+histogram("edad_anios","Edad, años")+histogram("imc_kg_m2","Índice de masa corporal, kg/m²")+histogram("caminata_6min_m","Distancia caminada, m")+'</div>');};
